ForMsgHdr* CSockIO::makeRequestMsg(FOREIGN_FUNCTIONS func, int dataLength, void *data)
{
	CRemTstApp *app = (CRemTstApp *) AfxGetApp();
	int msgLen = sizeof(ForMsgHdr) + dataLength;

	ForMsgHdr* pHdr = (ForMsgHdr *) new char[msgLen];
	pHdr->Function = func;
	pHdr->DataLength = dataLength;
	pHdr->Status = -1;
	pHdr->UserData = app->GetNewSeqNo();

	if ( (data != nullptr) && (dataLength > 0) )
		memcpy(&pHdr[1], data, dataLength);

	return pHdr;
}
